def smallest_divisor_ge_two_abs(x: int) -> int:
    n = abs(x)
    if n < 2:
        return 0
    for i in range(2, n + 1):
        if n % i == 0:
            return i
    return 0

def solution(x):
    n = abs(x)
    if n == 0:
        return 0
    if n & (n - 1) == 0:
        return 0
    return n.bit_length() - n.bit_count()
